typedef enum {
/* =======================================  ARM Cortex-M3 Specific Interrupt Numbers  ======================================== */
  Reset_IRQn                = -15,              /*!< -15  Reset Vector, invoked on Power up and warm reset                     */
  NonMaskableInt_IRQn       = -14,              /*!< -14  Non maskable Interrupt, cannot be stopped or preempted               */
  HardFault_IRQn            = -13,              /*!< -13  Hard Fault, all classes of Fault                                     */
  MemoryManagement_IRQn     = -12,              /*!< -12  Memory Management, MPU mismatch, including Access Violation
                                                     and No Match                                                              */
  BusFault_IRQn             = -11,              /*!< -11  Bus Fault, Pre-Fetch-, Memory Access Fault, other address/memory
                                                     related Fault                                                             */
  UsageFault_IRQn           = -10,              /*!< -10  Usage Fault, i.e. Undef Instruction, Illegal State Transition        */
  SVCall_IRQn               =  -5,              /*!< -5 System Service Call via SVC instruction                                */
  DebugMonitor_IRQn         =  -4,              /*!< -4 Debug Monitor                                                          */
  PendSV_IRQn               =  -2,              /*!< -2 Pendable request for system service                                    */
  SysTick_IRQn              =  -1,              /*!< -1 System Tick Timer                                                      */
/* ==========================================  lm3s9b92 Specific Interrupt Numbers  ========================================== */
  GPIOA_IRQn                =   0,              /*!< 0  GPIO A interrupt.                                                      */
  GPIOB_IRQn                =   1,              /*!< 1  GPIO B interrupt.                                                      */
  GPIOC_IRQn                =   2,              /*!< 2  GPIO C interrupt.                                                      */
  GPIOD_IRQn                =   3,              /*!< 3  GPIO D interrupt.                                                      */
  GPIOE_IRQn                =   4,              /*!< 4  GPIO E interrupt.                                                      */
  I2C0_IRQn                 =   8,              /*!< 8  Inter-Integrated Circuit 0 interrupt.                                  */
  WDT0_IRQn                 =  18,              /*!< 18 Watchdog Timer 0 and 1 interrupt.                                      */
  SYSCTL_IRQn               =  28,              /*!< 28 System Control interrupt.                                              */
  GPIOF_IRQn                =  30,              /*!< 30 GPIO F interrupt.                                                      */
  GPIOG_IRQn                =  31,              /*!< 31 GPIO G interrupt.                                                      */
  GPIOH_IRQn                =  32,              /*!< 32 GPIO H interrupt.                                                      */
  I2C1_IRQn                 =  37,              /*!< 37 Inter-Integrated Circuit 1 interrupt.                                  */
  GPIOJ_IRQn                =  54               /*!< 54 GPIO J interrupt.                                                      */
} IRQn_Type;



